function j({registerIndicator:x,nulls:p}){x({id:"oa-cfitz",name:"Christiano-Fitzgerald Band-Pass Filter (CFITZ)",category:"Filters",placement:"pane",inputs:[{key:"pLow",type:"number",label:"Min Period (pLow)",default:6,min:2,max:5e3,step:1,tooltip:"Shortest cycle to pass through (bars)"},{key:"pHigh",type:"number",label:"Max Period (pHigh)",default:32,min:3,max:5e3,step:1,tooltip:"Longest cycle to pass through (bars)"},{key:"maxLookback",type:"number",label:"Max Lookback",default:500,min:10,max:5e3,step:1,tooltip:"Maximum bars of history to use. Larger = better frequency resolution but slower. Zero-sum property is always maintained."}],plots:[{key:"cycle",type:"line",title:"CF Cycle",style:{color:"#00897b",lineWidth:2}}],levels:()=>[{price:0,title:"Zero",color:"#787b86",dashed:!0}],calc(u,l){const b=Math.max(2,Math.floor(Number(l.pLow)||6)),w=Math.max(3,Math.floor(Number(l.pHigh)||32)),k=Math.max(b+1,w),y=Math.max(10,Math.min(5e3,Math.floor(Number(l.maxLookback)||500))),r=u.length,e=new Array(r).fill(NaN);if(r===0)return{cycle:p(e)};const o=u.map(t=>t.close),a=t=>Number.isFinite(t)?t:0,f=2*Math.PI/k,M=2*Math.PI/b,c=(M-f)/Math.PI,n=y-1,s=new Array(n+1).fill(0),h=new Array(n+1).fill(0);for(let t=1;t<=n;t++)s[t]=(Math.sin(t*M)-Math.sin(t*f))/(Math.PI*t),h[t]=h[t-1]+s[t];for(let t=0;t<r;t++){if(t<1){e[t]=0;continue}if(t<2){e[t]=.5*c*(a(o[t])-a(o[t-1]));continue}let m=.5*c*a(o[t]);const d=Math.min(n,t-1);for(let i=1;i<=d;i++)m+=s[i]*a(o[t-i]);const g=h[d],L=-.5*c-g,P=Math.min(t,y);m+=L*a(o[t-P]),e[t]=m}return{cycle:p(e)}}})}export{j as default};
